import type { SubjectBank } from '@/types';

export const dramaBank: SubjectBank = {
  short: [
    { question: "What is 'proxemics' in drama?", answer: "Proxemics refers to the use of space and physical distance between performers on stage to communicate relationships, power and emotion. Close proximity may suggest intimacy or confrontation; distance may suggest formality or isolation.", acceptedAnswers: ["use of space and distance between performers to show relationship, power and emotion", "proxemics = how actors use physical distance to communicate relationship and status", "the use of physical distance between performers on stage to convey meaning", "how distance between actors communicates relationships and emotions"], marks: 2, hint: "The use of space and distance between actors" },
    { question: "What is the difference between naturalistic and non-naturalistic performance styles?", answer: "Naturalistic performance aims to represent everyday life realistically. Non-naturalistic performance uses stylised, exaggerated or symbolic techniques (e.g. physical theatre, Brechtian techniques) that draw attention to the theatrical process.", acceptedAnswers: ["naturalistic = realistic everyday life; non-naturalistic = stylised/symbolic/Brechtian", "naturalistic represents real life; non-naturalistic uses stylised, exaggerated or abstract techniques", "naturalistic: lifelike and realistic; non-naturalistic: stylised, physical or Brechtian", "naturalistic aims for realism; non-naturalistic uses theatrical conventions openly"], marks: 2, hint: "Real-life representation vs stylised, symbolic approaches" },
    { question: "What does 'ensemble performance' mean?", answer: "Ensemble performance is when a group of performers work together with equal importance and collaborative technique, often without a single protagonist. Emphasises collective storytelling.", acceptedAnswers: ["group of performers working together with equal importance and collaborative technique", "all performers equally important; collective storytelling without a single protagonist", "ensemble = collaborative performance where no one actor is more important than another", "group performance based on collaboration and equal contribution"], marks: 1, hint: "Group performance — all performers are equally important" },
    { question: "Name two Brechtian techniques and explain their purpose.", answer: "Any two: Direct address (actors speak to audience — breaks the fourth wall); Placards/captions (display scene titles — remind audience they are watching a play); Narration; Multi-role; Gestus. Purpose: Verfremdungseffekt — to make the audience think critically rather than become emotionally absorbed.", acceptedAnswers: ["direct address (breaks 4th wall) and placards/captions (Verfremdungseffekt — make audience think critically)", "e.g. direct address and narration — create alienation effect to make audience think rather than feel", "two techniques: direct address (speaks to audience) and multi-role; both create alienation", "placards/captions and direct address — both prevent emotional absorption and provoke critical thought"], marks: 2, hint: "Brecht wanted audiences to think, not just feel." },
    { question: "What is Stanislavski's 'Magic If'?", answer: "The 'Magic If' asks an actor to imagine: 'What would I do IF I were in this character's situation?' It helps actors find genuine emotional responses by imagining themselves in the given circumstances, rather than imitating emotions mechanically.", acceptedAnswers: ["asking 'what would I do IF I were in this character's situation?' to find genuine responses", "Stanislavski's Magic If: actor imagines being in the character's circumstances to unlock authentic emotion", "'what would I do if I were in this situation?' — helps actors find truthful emotional responses", "imagining yourself in the character's circumstances to produce authentic reactions"], marks: 2, hint: "A tool Stanislavski gave actors to unlock authentic emotional responses" },
    { question: "What is the 'Verfremdungseffekt' in Brecht's Epic Theatre?", answer: "The Verfremdungseffekt (alienation or estrangement effect) is Brecht's technique of making the familiar seem strange. By preventing emotional immersion, it prompts the audience to think critically about the social and political issues presented, rather than simply feeling emotions.", acceptedAnswers: ["alienation/estrangement effect — making familiar seem strange to prevent emotional immersion and provoke critical thought", "Brecht's technique of stopping the audience from emotionally absorbing the play so they think critically", "alienation effect: prevents emotional involvement so audience can think about social issues", "making the familiar seem strange — prevents empathy and encourages rational critical analysis"], marks: 2, hint: "Also called the alienation effect — making the familiar seem strange to provoke thought" },
    { question: "Name the four main staging configurations used in theatre.", answer: "Proscenium arch (audience on one side, picture-frame stage); Thrust/apron (stage extends into audience on three sides); Traverse (audience on two sides, stage in between); In-the-round (audience surrounds the stage on all sides).", acceptedAnswers: ["proscenium arch, thrust/apron, traverse, in-the-round", "four stagings: proscenium (audience one side), thrust (three sides), traverse (two sides), in-the-round (all sides)", "proscenium arch, thrust stage, traverse stage, and theatre in-the-round", "the four main types are: proscenium, thrust, traverse, and in-the-round"], marks: 2, hint: "How is the audience positioned relative to the stage?" },
    { question: "What is 'gestus' in Brecht's Epic Theatre?", answer: "Gestus is a characteristic gesture, posture or attitude that reveals a character's social position and attitude. It is deliberate and representative — showing class, power and social relationships rather than individual psychology.", marks: 2, hint: "A gesture that shows a character's social attitude and class position" },
    { question: "What is 'emotional memory' in Stanislavski's System?", answer: "Emotional memory (affective memory) is the technique of recalling a real personal emotional experience to generate authentic emotion on stage. The actor accesses genuine feelings from their own life to make the performance truthful.", marks: 2, hint: "Recalling real personal experiences to produce genuine emotion in performance" },
    { question: "What is 'Theatre of Cruelty' associated with Antonin Artaud?", answer: "Artaud's Theatre of Cruelty aimed to assault the audience's senses — using sound, light, spectacle and physical space — to break down their rational defences and create a visceral, almost ritual experience. 'Cruelty' referred to rigour and intensity, not violence.", marks: 2, hint: "Artaud wanted to shock and assault the senses — a visceral, ritualistic experience" },
    { question: "What does 'multi-role' mean as a performance technique?", answer: "Multi-role is when one performer plays several different characters in the same production. It is associated with non-naturalistic theatre and Brechtian technique, drawing attention to the actor's craft and preventing the audience from forgetting they are watching a performance.", marks: 1, hint: "One actor playing more than one character" },
    { question: "Define 'subtext' in drama.", answer: "Subtext is the underlying meaning in a scene — what characters truly think or feel beneath what they say. A character may say 'I'm fine' while the subtext reveals deep unhappiness. Naturalistic actors must be aware of and play the subtext.", marks: 2, hint: "What is really meant beneath what is actually said" },
    { question: "What is a soliloquy?", answer: "A soliloquy is a dramatic device where a character speaks their thoughts aloud, alone on stage (or apparently unheard by others). It allows the audience direct access to the character's inner mind, true feelings and intentions.", marks: 1, hint: "A character's private thoughts spoken aloud — the audience can hear but other characters cannot" },
    { question: "What is 'physical theatre' as a performance style?", answer: "Physical theatre is a style where the body is the primary storytelling tool. Performers use movement, gesture and physicality rather than words to communicate narrative and emotion. Associated practitioners include Frantic Assembly, DV8 and Complicité.", marks: 2, hint: "The body tells the story, not words — movement, gesture and physicality" },
    { question: "What is 'in medias res' and how is it used in drama?", answer: "In medias res is a Latin term meaning 'into the middle of things'. It describes a play or scene that begins in the middle of the action, without lengthy exposition. This creates immediate dramatic tension and draws the audience in from the opening moment.", marks: 2, hint: "Starting in the middle of the action rather than the beginning" },
    { question: "What is Frantic Assembly's approach to devising theatre?", answer: "Frantic Assembly (Scott Graham and Steven Hoggett) use physical theatre and movement-based devising. Their 'Hymn Hands', 'Chair Duets' and 'Round, By Through' are physical building blocks. They work collaboratively, building scenes from physical images rather than text first.", marks: 2, hint: "Physical building blocks — Hymn Hands, Chair Duets — collaborative movement-based devising" },
    { question: "What is a 'given circumstance' in Stanislavski's System?", answer: "Given circumstances are the facts of a character's situation provided by the playwright: who they are, where they are, when the scene takes place, what has happened before and what they want. Actors must understand and believe all given circumstances to perform authentically.", marks: 2, hint: "The facts about a character's world established by the playwright" },
    { question: "What is a 'proscenium arch' stage?", answer: "A proscenium arch stage has a large arch or frame that separates the stage from the auditorium. The audience sit on one side and watch through the 'picture frame'. It creates a formal distance between performers and audience and is the most common configuration in traditional theatres.", acceptedAnswers: ["stage framed by an arch with audience on one side viewing through a picture frame", "traditional stage with arch separating stage and audience — audience on one side only", "proscenium arch creates a picture-frame effect with audience on one side"], marks: 2, hint: "The traditional theatre layout — audience on one side looking through an arch" },
    { question: "What is 'traverse' staging?", answer: "Traverse staging places the stage between two banks of seating, with the audience on either side. The action takes place in a long central corridor. It is good for processional narratives and creates a sense of journey.", acceptedAnswers: ["stage between two banks of audience on either side — like a catwalk or corridor", "audience on two opposite sides with stage in the middle", "traverse: stage in the centre with audience left and right"], marks: 2, hint: "Audience on two sides — the stage runs between them like a corridor" },
    { question: "What is 'theatre in the round'?", answer: "Theatre in the round places the stage in the centre with the audience surrounding it on all sides. This creates maximum intimacy and vulnerability — actors cannot hide from any angle. Audience members can see each other across the stage, creating a sense of community.", acceptedAnswers: ["audience surrounds the stage on all sides", "stage in the centre with audience all around it", "in-the-round: maximum intimacy, audience on all sides, actors cannot hide"], marks: 2, hint: "Audience surrounds the stage completely — maximum intimacy" },
    { question: "What does 'blocking' mean in theatre?", answer: "Blocking refers to the pre-planned movement of actors on stage — where they stand, when they move, and where they move to. Directors plan blocking to ensure all performers can be seen, to create visual composition, and to communicate relationships and meaning.", acceptedAnswers: ["pre-planned movements of actors on stage — where they stand and move", "the planning of actors' positions and movements on stage", "blocking = the director's plan for where actors move and stand"], marks: 2, hint: "Pre-planned movements of actors on stage" },
    { question: "What is the 'super-objective' in Stanislavski's System?", answer: "The super-objective is the overarching want or goal that drives a character throughout the entire play. All smaller scene objectives serve the super-objective. For example, Macbeth's super-objective might be 'to gain and keep power'.", acceptedAnswers: ["the character's overarching goal throughout the whole play", "the main driving want that motivates a character across the entire play", "super-objective = the overall goal that all smaller objectives serve"], marks: 2, hint: "The character's single most important want across the whole play" },
    { question: "What is a 'cyclorama'?", answer: "A cyclorama (or 'cyc') is a large curved backdrop, usually white or pale blue, at the rear of the stage. It can be lit in many colours to suggest sky, atmosphere or abstract mood. It creates depth and can be used to project images onto.", acceptedAnswers: ["large curved white/pale backdrop at the rear of the stage, lit to suggest sky or atmosphere", "curved backdrop at the back of the stage used for atmospheric lighting and projections", "a large plain backdrop that can be lit in different colours to suggest atmosphere"], marks: 2, hint: "The large curved backdrop at the back of the stage — lit in different colours" },
    { question: "What is a 'fresnel' lantern in stage lighting?", answer: "A fresnel is a type of stage lantern with a stepped lens that produces a soft-edged, even wash of light. It can be focused (concentrated) or flooded (spread wide) and is used for general stage illumination and as a fill light.", acceptedAnswers: ["stage lantern with a stepped lens producing a soft-edged wash of light", "type of stage light with soft-edged beam — used for general illumination", "fresnel: stepped lens lantern giving soft-edged light, can be flooded or concentrated"], marks: 2, hint: "A stage lantern with a soft-edged beam — versatile and common" },
    { question: "What is a 'gobo' in stage lighting?", answer: "A gobo is a thin metal or glass disc placed inside a profile lantern to project a pattern of light onto the stage. Gobos can project leaf patterns, window shapes, brick textures, abstract patterns or location-specific images.", acceptedAnswers: ["a metal or glass disc placed in a profile lantern to project a pattern of light", "gobos project patterns (leaves, windows, abstract shapes) onto the stage", "a stencil placed in a lantern to project a pattern onto the stage"], marks: 2, hint: "A stencil that goes inside a lantern to project a pattern of light onto the stage" },
    { question: "What is the difference between 'diegetic' and 'non-diegetic' sound in theatre?", answer: "Diegetic sound exists within the world of the play — the characters can hear it (e.g. a phone ringing, music playing on a radio on stage). Non-diegetic sound is added for the audience's benefit only — characters cannot hear it (e.g. underscoring, sound effects used to create atmosphere).", acceptedAnswers: ["diegetic = sounds characters can hear; non-diegetic = sounds only the audience hears", "diegetic exists in the play's world; non-diegetic is added for audience effect only", "diegetic: character hears it; non-diegetic: only audience hears it — like underscoring"], marks: 2, hint: "Can the characters on stage hear the sound?" },
    { question: "What is 'dramatic irony'?", answer: "Dramatic irony occurs when the audience knows something that one or more characters on stage do not. This creates tension, suspense, or dark comedy, as the audience watches characters act without the knowledge the audience possesses.", acceptedAnswers: ["when the audience knows something the characters do not", "audience has more information than one or more characters — creates tension or suspense", "dramatic irony: we know the truth but characters don't"], marks: 2, hint: "The audience knows something the characters on stage do not" },
    { question: "What does 'verbatim theatre' mean?", answer: "Verbatim theatre is a form of documentary theatre where the script is made entirely from real people's own words, taken from interviews, court transcripts, or public documents. Performers speak the exact words of real people, creating a direct link between theatre and real events.", acceptedAnswers: ["theatre using real people's exact words from interviews or documents as the script", "verbatim = documentary theatre using actual spoken words of real people", "performers speak real people's words taken from interviews or transcripts"], marks: 2, hint: "Theatre made entirely from real people's own words — documentary in style" },
    { question: "What is 'site-specific theatre'?", answer: "Site-specific theatre is performed in a non-traditional venue specifically chosen to suit the narrative or themes — a factory, hospital, street, or woodland. The location becomes part of the storytelling, giving the performance a sense of reality and place impossible in a conventional theatre.", acceptedAnswers: ["theatre performed in a non-traditional venue chosen for its relationship to the story", "performance in a specific real-world location like a factory or street", "site-specific: the venue is chosen because it directly relates to the story being told"], marks: 2, hint: "Theatre performed somewhere specific — not in a traditional theatre building" },
    { question: "What is 'absurdist theatre'? Name one playwright associated with it.", answer: "Absurdist theatre presents a world where life has no inherent meaning, logic, or purpose. Characters are trapped in meaningless repetitions or impossible situations. Associated with Samuel Beckett (Waiting for Godot) and Harold Pinter. Theatre of the Absurd emerged in the 1950s.", acceptedAnswers: ["theatre presenting a meaningless or illogical world — Beckett's Waiting for Godot", "absurdism: no purpose or logic in life; characters in futile situations; Beckett/Pinter", "absurdist theatre: characters trapped in meaningless situations — associated with Samuel Beckett"], marks: 2, hint: "A world with no meaning — characters often wait or repeat actions pointlessly. Think Beckett." },
    { question: "What are the three components (parts) of AQA GCSE Drama?", answer: "Component 1: Devising Theatre (40%) — students create and perform an original piece of theatre and produce a portfolio. Component 2: Scripted Performance (20%) — students perform from a published script. Component 3: Theatre Makers in Practice (40%) — written exam covering a set play and a live theatre review.", acceptedAnswers: ["Component 1: Devising (40%); Component 2: Scripted Performance (20%); Component 3: Written Exam (40%)", "devising, scripted performance, and written exam (set play and live theatre review)", "AQA Drama: C1 devising (portfolio + performance), C2 scripted, C3 written exam"], marks: 2, hint: "Devising, scripted performance, and the written exam — what percentages are they worth?" },
    { question: "What is 'pitch' as a vocal skill in performance?", answer: "Pitch refers to how high or low a voice is. Actors vary pitch to express emotion, status and character — a higher pitch may suggest nervousness, youth or excitement; a lower pitch may convey authority, calm or menace.", acceptedAnswers: ["how high or low the voice is — varied to show emotion, status and character", "pitch = high or low voice quality; high suggests nervousness; low suggests authority", "the highness or lowness of a performer's voice"], marks: 1, hint: "How high or low is the voice?" },
    { question: "What is 'pace' as a vocal skill in performance?", answer: "Pace is the speed at which an actor speaks. Fast pace can convey excitement, panic or urgency; a slow, deliberate pace can suggest authority, sadness or menace. Varying pace keeps an audience engaged and avoids monotony.", acceptedAnswers: ["the speed at which an actor speaks — fast for urgency, slow for authority", "how quickly or slowly a performer delivers their lines", "pace = speech speed; fast pace = panic/urgency; slow pace = authority/sadness"], marks: 1, hint: "How fast or slowly does the actor speak?" },
    { question: "What is 'pause' as a vocal skill in performance?", answer: "A pause is a deliberate silence during speech. Pauses create tension, give the audience time to process important information, suggest that a character is thinking or struggling to speak, and can be more powerful than words. Strategic pauses are a key tool of experienced performers.", acceptedAnswers: ["deliberate silence that creates tension, emphasis or suggests thought", "a planned silence during speech — powerful tool for tension and meaning", "pause: deliberate silence used for tension, thought or emphasis"], marks: 1, hint: "A deliberate silence — sometimes more powerful than any word" },
    { question: "What is 'projection' as a vocal skill?", answer: "Projection is the ability to make the voice carry clearly to all members of the audience without shouting. Good projection uses breath support and resonance rather than forced volume. It ensures the audience can hear and understand every word clearly.", acceptedAnswers: ["making the voice carry clearly to all audience members without shouting", "using breath and resonance to carry the voice clearly — not just speaking louder", "projection = voice carrying clearly to all areas of the auditorium"], marks: 1, hint: "Making your voice carry to all parts of the theatre without shouting" },
    { question: "What is 'articulation' as a vocal skill?", answer: "Articulation is the clarity with which words and sounds are formed. Clear articulation (using lips, teeth and tongue precisely) ensures that every word is understood. Poor articulation makes speech mumbled or indistinct.", acceptedAnswers: ["the clarity and precision with which sounds and words are formed", "using lips, teeth and tongue precisely so every word is clearly understood", "articulation = clear formation of words — ensuring the audience understands every word"], marks: 1, hint: "How clearly and precisely words are formed and spoken" },
    { question: "What is 'naturalism' in theatre, and which practitioner is most associated with it?", answer: "Naturalism is a theatrical style that attempts to represent everyday life as accurately as possible on stage, using realistic sets, costumes, speech and behaviour. It is most closely associated with Konstantin Stanislavski, whose System developed techniques to help actors achieve truthful, lifelike performance.", acceptedAnswers: ["a style representing everyday life as realistically as possible; associated with Stanislavski", "naturalism = lifelike representation of reality; Stanislavski developed techniques to achieve this", "realistic theatre where everything imitates real life — Stanislavski is the key practitioner"], marks: 2, hint: "The style that aims to represent real life as accurately as possible — which practitioner?" },
    { question: "What is 'chiaroscuro' in lighting design?", answer: "Chiaroscuro (from Italian: 'light-dark') in lighting design refers to the use of strong contrasts between lit and unlit areas of the stage, creating dramatic shadows. It creates tension, mystery and atmosphere, drawing attention to specific performers or areas while leaving others in darkness.", acceptedAnswers: ["strong contrast between lit and unlit areas on stage creating dramatic shadows", "light and dark contrast in stage lighting — creates mystery, tension and atmosphere", "chiaroscuro lighting: harsh contrast between light and shadow on stage"], marks: 2, hint: "Dramatic contrast between light and shadow on stage — from the Italian for light and dark" },
    { question: "What is 'expressionism' as a theatrical style?", answer: "Expressionism is a non-naturalistic style where the external world is distorted to represent the internal emotional or psychological state of a character. Sets may be skewed, colours exaggerated, and performances stylised to show subjective experience rather than objective reality.", acceptedAnswers: ["distorting external reality to express a character's internal emotional state", "expressionism: skewed sets, exaggerated colour, stylised performance to show inner experience", "non-naturalistic style where the stage world reflects a character's psychological state"], marks: 2, hint: "When the stage world reflects a character's inner emotional world — distorted, not realistic" },
    { question: "What is 'direct address' in theatre?", answer: "Direct address is when a performer speaks directly to the audience, breaking the fourth wall. It is a key Brechtian technique used to create the alienation effect, but is also used in other contexts — Shakespearean soliloquies, pantomime, and one-person shows all use direct address.", acceptedAnswers: ["when a performer speaks directly to the audience, breaking the fourth wall", "actor addresses the audience directly — breaks the fourth wall", "direct address: performer speaks to audience rather than staying within the play's world"], marks: 1, hint: "When the actor talks directly to the audience, stepping out of the play's world" },
    { question: "What is 'gait' as a physical performance skill?", answer: "Gait refers to the way a character walks — their stride length, posture, speed, weight distribution, and whether they walk with purpose, hesitation, confidence or infirmity. Gait is a powerful physical characterisation tool that communicates age, status, health and personality.", acceptedAnswers: ["the way a character walks — stride, posture, weight and pace communicating personality", "how a performer walks to convey character — age, status, health, confidence", "gait = style of walking used to characterise a role"], marks: 1, hint: "The way the character walks — what does it reveal about them?" },
    { question: "What is the 'apron' of a stage?", answer: "The apron is the part of the stage that extends beyond the proscenium arch into the auditorium. It brings performers closer to the audience and can be used to create intimacy, deliver direct address, or perform scenes separate from the main stage action.", acceptedAnswers: ["the part of the stage that extends forward beyond the proscenium arch into the auditorium", "stage extension beyond the arch — brings performers closer to the audience", "apron = the forward part of a proscenium stage extending into the audience area"], marks: 1, hint: "The part of the stage that sticks out towards the audience beyond the arch" },
    { question: "What is a 'profile' (or 'spotlight') lantern in stage lighting?", answer: "A profile lantern (also called a profile spot or ellipsoidal) produces a sharp, clean-edged beam of light that can be shaped precisely using shutters or an iris. It is ideal for specials (highlighting specific areas), projecting gobos, and long throws.", acceptedAnswers: ["a lantern producing a sharp-edged, precisely controlled beam of light", "profile spot: sharp-edged beam that can be shaped with shutters; used for specials and gobos", "profile lantern gives a precise, hard-edged pool of light — can project gobos"], marks: 2, hint: "The lantern that gives a sharp, precise beam — can be shaped with shutters" },
    { question: "What is 'devised theatre'?", answer: "Devised theatre is original theatre created collaboratively by a company without a pre-existing script. The work is generated through improvisation, research, discussion and physical exploration. The devising process is as important as the final product.", acceptedAnswers: ["original theatre created collaboratively without a pre-existing script", "theatre made from scratch through improvisation and collaboration", "devised theatre = company creates its own work through improvisation and research"], marks: 1, hint: "Theatre that starts with no script — the company creates everything together" },
    { question: "What does 'Steven Berkoff' bring to physical theatre performance?", answer: "Steven Berkoff developed a highly stylised, physical approach to performance influenced by Brecht, mime and martial arts. His work uses exaggerated physicality, chorus work, slow motion, and direct address. He adapted Greek tragedies and Kafka, using minimal set and maximum physical expression.", acceptedAnswers: ["stylised, exaggerated physicality; chorus work; minimal set; influenced by Brecht and mime", "Berkoff: highly physical, exaggerated, Brechtian style — Greek tragedy and Kafka adaptations", "exaggerated physical theatre style using chorus, slow motion and direct address"], marks: 2, hint: "Exaggerated physicality, Brechtian influence, chorus work — minimal set, maximum body" },
    { question: "What are 'wings' in theatre?", answer: "The wings are the offstage areas to the left and right of the acting area in a proscenium arch or end-on stage. Performers wait in the wings before their entrance; scenery is stored and changed in the wings. They are hidden from the audience's view.", acceptedAnswers: ["the offstage areas to the sides of the acting area where actors wait to enter", "left and right offstage spaces hidden from the audience — actors wait and scenery is stored", "wings: hidden side areas of the stage where performers wait and exits occur"], marks: 1, hint: "The hidden areas to the sides of the stage where actors wait to enter" },
    { question: "What is the difference between 'prompt side' (PS) and 'opposite prompt side' (OP) in theatre?", answer: "Prompt side (PS) is stage left (from the actor's perspective facing the audience) — traditionally where the prompt stands with the script. Opposite prompt side (OP) is stage right. These terms are used in the UK to communicate stage positions.", acceptedAnswers: ["PS = stage left; OP = stage right (from the actor's perspective facing audience)", "prompt side is stage left; opposite prompt is stage right", "PS: stage left (actor facing audience); OP: stage right — traditional UK staging terms"], marks: 2, hint: "From the actor facing the audience: which side is 'prompt side' and which is 'opposite'?" },
    { question: "What is 'documentary theatre'?", answer: "Documentary theatre creates performance from real historical events, using actual documents, speeches, interviews and evidence as source material. It aims to present factual information in a dramatic form, prompting audiences to engage with real issues. Verbatim theatre is a type of documentary theatre.", acceptedAnswers: ["theatre created from real documents, interviews and historical material", "documentary theatre: performance based on real events and real people's words", "theatre using actual historical or journalistic material as its script"], marks: 2, hint: "Theatre based on real events and real documents — a kind of theatrical journalism" },
  ],
  mid: [
    { question: "Explain how a director might use stage space, levels and lighting to create tension in a scene.", answer: "A director places characters downstage centre for power and focus; isolating a character upstage creates vulnerability. Levels (one character elevated on a chair/platform, another lower) communicate power imbalance. Tight, focused spotlights isolate characters; dim, blue or low-key lighting creates unease. Shadows suggest mystery or danger. Freeze frames or slow motion heighten tension by focusing attention on a critical moment. The use of darkness beyond the acting area implies threat.", marks: 4, hint: "Cover: staging position, levels, lighting colour/intensity, and their emotional effect on the audience" },
    { question: "How might a designer use costume to communicate character and theme in a production?", answer: "Costume communicates status (formal dress vs. workwear), period, personality and emotional state. Colour carries symbolic meaning: white (innocence/purity), black (authority/death), red (danger/passion). Condition of costume reveals character: a frayed coat suggests poverty; pristine clothes suggest wealth. Costume can show change: a character's transformation shown through changing clothes. In non-naturalistic theatre, costume may be symbolic rather than realistic — e.g. all characters in grey to suggest conformity. Accessories (hats, gloves) can convey status and social role.", marks: 4, hint: "Cover: colour symbolism, status, period, condition of costume, and how it changes across the play" },
    { question: "Explain how Stanislavski's concept of 'units and objectives' helps an actor prepare a role.", answer: "Stanislavski divided a script into 'units' (beats) — small sections where the character has a single objective (what they want in that moment). Each unit has an objective ('I want to persuade her') and the overarching want is the 'super-objective' (what the character wants across the whole play). Breaking a role into units helps actors understand motivation moment-by-moment. Objectives should be active and transitive ('to convince', 'to seduce', 'to frighten'). This technique prevents actors from indicating emotion; they pursue objectives and let emotions arise naturally.", marks: 5, hint: "Define units, objectives and super-objective. Explain how active, transitive verbs keep performance genuine rather than generalised" },
    { question: "How might a director use the staging configuration to affect the audience's relationship with the performance?", answer: "Proscenium arch creates distance and formality — audience observe as if through a window; good for spectacle and large-scale design. Thrust staging brings audiences on three sides closer to the action, creating intimacy and making it harder for actors to hide. In-the-round surrounds the stage, creating maximum intimacy and vulnerability — no upstage escape for actors; audiences see each other, enhancing community. Traverse creates a corridor of action — useful for processional narrative. The choice of configuration shapes how much the audience feels inside or outside the world of the play.", marks: 4, hint: "For each configuration describe how the physical relationship between audience and performer changes the experience" },
    { question: "How does Brecht use 'direct address' to create the alienation effect, and why did he consider this politically important?", answer: "Direct address breaks the fourth wall — actors speak directly to the audience, acknowledging them as spectators rather than pretending they are invisible. This shatters emotional immersion and reminds the audience they are watching a constructed narrative about social reality. For Brecht, emotional immersion (as in Stanislavski's naturalism) was politically dangerous because it led audiences to empathise with characters without questioning the social structures causing their suffering. By being alienated, audiences could think clearly: Is this social situation inevitable? Could it be changed? Direct address turns theatre from entertainment into a political tool for social awareness and change.", marks: 5, hint: "Explain what direct address is, how it creates alienation, and Brecht's political reasoning — theatre as a tool for social change" },
    { question: "Analyse how sound design can be used to create atmosphere and communicate meaning in a theatre production.", answer: "Sound design functions on two levels: diegetic (sounds that exist within the world of the play — traffic, voices, music a character plays) and non-diegetic (sounds added for effect that characters cannot hear). Volume controls focus and tension — a sudden silence after loud noise is more powerful than noise alone. Underscoring (music beneath dialogue) shapes emotional response without audience awareness. Sound motifs (a recurring musical phrase associated with a character or theme) create structural cohesion. Live sound vs recorded: live sound (actors playing instruments) adds authenticity; recorded sound can be manipulated (echo, distortion) for non-naturalistic effect. Silence itself is a design choice with enormous power.", marks: 5, hint: "Cover: diegetic vs non-diegetic, volume, underscoring, motifs, live vs recorded, and the power of silence" },
    { question: "Explain the devising process that a theatre company might use when creating a new piece of theatre from a stimulus.", answer: "The devising process typically begins with exploring the stimulus through physical and verbal improvisation — generating material without judgment. The company collects and filters ideas, identifying the most dramatically compelling. Research follows: contextual, historical or artistic research to deepen the work. Structuring is key: deciding the order of scenes, how narrative is communicated, what the audience should feel at each moment. Rehearsal and refinement through showing work to each other and responding. A design concept (set, costume, lighting) is developed alongside the performance. Evaluation is ongoing — performers constantly assess what is working and why.", marks: 5, hint: "Cover: stimulus exploration, improvisation, research, structuring, rehearsal/refinement, design, and evaluation" },
    { question: "How might a performer use voice to distinguish between two contrasting characters in a multi-role performance?", answer: "A performer uses pitch (higher voice for a young or nervous character; lower, resonant voice for authority), pace (fast speech for anxiety or youth; slow, deliberate pace for power or age), pause (strategic silence communicates thought, power and emotional weight), volume (whispered intimacy vs projected authority), accent and dialect (reveals regional/social background), and articulation (crisp, clipped speech for formal characters; loose, flowing speech for relaxed ones). Physical changes between characters anchor the vocal shift — a change in posture, level or spatial position helps the audience distinguish between roles.", marks: 4, hint: "Cover: pitch, pace, pause, volume, accent, and articulation — with examples of contrasting characters" },
    { question: "Explain how a set designer might use colour, levels and space to communicate the themes of a play.", answer: "Colour in set design carries symbolic meaning: neutral/grey suggests oppression or conformity; warm colours suggest vitality and warmth; cold blues and whites suggest isolation or death. Levels provide physical metaphors — elevated areas represent power, status or aspiration; low, flat space suggests vulnerability or equality. Space management: a cluttered, claustrophobic set suggests confinement and social pressure; a bare, open stage creates exposure and vulnerability. Symbolic set elements (a locked door, a broken clock) can reinforce themes. Revolving or transforming set can show time passing or the collapse of a character's world.", marks: 5, hint: "Cover: colour symbolism, levels as metaphor, space and confinement, symbolic objects, and transforming/flexible set design" },
    { question: "Describe how a performer might use physicality to portray a character's emotional journey across a play.", answer: "A performer charts the character's physical change: upright, expansive posture communicates confidence at the start; as the character experiences trauma or guilt, the body closes (hunched shoulders, lowered gaze, protective arm positions, smaller footprint). Gesture: large, open gestures suggest openness and control; small, contained or involuntary gestures (nervous hand movements) reveal inner anxiety. Movement quality: fluid, purposeful movement for a character in control; hesitant, broken movement for one suffering. Proximity to others changes as relationships shift. Physical collapse can mark a turning point in the narrative.", marks: 5, hint: "Track physical change from beginning to end — posture, gesture, movement quality, proxemics" },
    { question: "Explain how a lighting designer might create mood and atmosphere using colour, intensity and direction of light.", answer: "Colour: warm amber or gold suggests comfort and warmth; cold blue or white suggests isolation, clinical environments or winter; red can suggest danger, passion or hellish threat; green creates an eerie, supernatural quality. Intensity: full brightness creates clarity and safety; dimmed light creates unease and intimacy; near-darkness suggests danger or the unconscious. Direction: top lighting creates harsh shadows, making faces gaunt and mysterious; side lighting (chiaroscuro) creates dramatic shadow; front lighting removes shadows for clear visibility; back lighting can silhouette figures, reducing them to outline. Combining these three variables gives a lighting designer enormous control over an audience's emotional response.", marks: 5, hint: "Cover colour (associations), intensity (bright to dark), and direction (top, side, front, back) — link each to its emotional effect" },
    { question: "Explain how Artaud's Theatre of Cruelty differs from Stanislavski's naturalistic approach, and what each demands of the audience.", answer: "Stanislavski's naturalism asks the audience to forget they are in a theatre — to believe in the fictional world, empathise with characters, and experience emotions vicariously. The fourth wall is maintained; the relationship is observational. Artaud's Theatre of Cruelty demands total sensory engagement — the audience is not an observer but a participant in a collective, ritual experience. Artaud placed the audience in the centre, surrounded them with performers and sensory stimuli (light, sound, smell, space) to break down rational defences. Naturalism works on emotion through identification; Artaud works through physical sensation and instinct. Naturalism is about understanding characters; Theatre of Cruelty is about experiencing something beyond rational comprehension.", marks: 5, hint: "Compare what each demands of the audience: Stanislavski = emotional identification; Artaud = sensory assault and ritual participation" },
    { question: "Describe how a playwright uses dramatic structure to build and release tension across a play you have studied.", answer: "Dramatic structure is the sequence of events designed to control the audience's emotional engagement. Exposition introduces characters and establishes the world; the inciting incident disrupts the status quo. Rising action escalates tension through complications, revelations and conflict. The crisis point is the moment of highest tension — the audience is most uncertain about the outcome. The climax is the turning point where the central conflict is resolved. Resolution (denouement) releases tension and provides closure. Structural devices: dramatic irony (audience knows more than characters); foreshadowing (hints at future events); reversal (fortunes change unexpectedly). Each structural element should be linked to a specific play with reference to scenes or moments.", marks: 5, hint: "Identify each structural stage: exposition, inciting incident, rising action, crisis, climax, resolution. Use a specific play." },
    { question: "Explain the role of the director in creating a production concept and communicating it to the design team.", answer: "The director develops a production concept — a unified vision for how the play will be staged, what themes will be emphasised, and the aesthetic world of the production. This concept shapes every design decision. The director communicates this through: initial design meetings where the concept is presented verbally and visually (mood boards, reference images); discussions with each designer about how their area of design serves the concept; rehearsal — working with performers to realise the concept physically and vocally. The director also considers audience positioning and relationship, and makes decisions about all staging. A strong production concept ensures all elements (set, costume, lighting, sound, performance) work as a coherent unified whole.", marks: 5, hint: "Cover: what a production concept is, how it is developed, how it is communicated to designers, and how it unifies all elements" },
    { question: "Compare how Frantic Assembly and Stanislavski approach the creation of character and scene work.", answer: "Stanislavski's approach is text-first and psychology-first: actors analyse the script, identify given circumstances, define objectives and use emotional memory to build a character from the inside out. The physical behaviour follows psychological truth. Frantic Assembly's approach is movement-first: scenes are built from physical images, contact work and spatial relationships (Hymn Hands, Chair Duets, Round By Through). Character emerges from physical interaction and spatial negotiation rather than psychological analysis. Stanislavski seeks psychological realism; Frantic Assembly seeks physical truth. Both approaches aim for authentic performance but through opposite means. Frantic Assembly is particularly effective for stories about embodied experience — desire, conflict, intimacy — because it starts with the body's truth.", marks: 5, hint: "Compare starting points (text/psychology vs movement/body), methods (emotional memory vs physical exercises), and what each achieves" },
  ],
  long: [
    { question: "Evaluate a theatrical performance you have studied, analysing how the director or performers used theatrical elements to communicate the play's themes. (8 marks)", answer: "[Reference a specific studied performance.] Introduction identifying the production and its central themes. Analysis of at least three theatrical elements: use of space/staging; characterisation and physicality; voice (pitch, pace, pause, projection); lighting design; sound design; costume; set design. Each element should be linked explicitly to the theme communicated. Evaluation of effectiveness should include reference to the audience's response. Conclusion judging the overall success of the production in communicating its message.", marks: 8, hint: "Identify a specific production. Analyse 3+ theatrical elements. Link each to theme. Include evaluation of effectiveness and audience response." },
    { question: "Compare how Stanislavski and Brecht approached the role of the actor in creating performance. Evaluate which approach is more effective for communicating social or political ideas. (10 marks)", answer: "Stanislavski: The System demands psychological truth. The actor builds a character from the inside out — emotional memory, given circumstances, the Magic If, units and objectives — to produce naturalistic performance where the audience believe the character is real. The fourth wall is maintained; the audience should forget they are watching a play. This creates empathy and emotional investment, which can make social issues personally affecting. Brecht: Epic Theatre demands critical detachment. Actors present characters to the audience rather than becoming them — they show the character's social position (gestus) and use direct address, multi-role and stylisation to prevent emotional absorption. The audience must think, not just feel. Evaluation: For communicating social/political ideas, Brechtian theatre is arguably more effective because it keeps the audience intellectually engaged. However, Stanislavski's emotional investment can make social injustice viscerally affecting in ways that Brechtian distance cannot. The most effective politically engaged theatre often combines both approaches.", marks: 10, hint: "Define each approach clearly, contrast their methods, and evaluate which better serves political/social theatre — consider both sides" },
    { question: "Analyse how a playwright uses dramatic structure and theatrical devices to build tension and engage the audience throughout a play you have studied. (10 marks)", answer: "[Reference a specific play e.g. DNA by Dennis Kelly, Blood Brothers by Willy Russell, or An Inspector Calls.] Analysis should cover: exposition (how the world is established and tension is seeded early); inciting incident (the event that triggers the main action); rising action (how tension escalates through scenes and revelations); crisis points (moments of maximum tension); climax (the turning point); resolution (how tension is released or left unresolved). Dramatic devices: dramatic irony (audience knows more than characters); foreshadowing; secrets and revelations; use of time (real time, compressed time, flashback); structural patterns (repetition, reversal). Link each structural element to its effect on the audience at that moment. Evaluation: judge how effectively the playwright maintains tension and what theatrical craft is demonstrated.", marks: 10, hint: "Analyse structure as a craft choice — exposition, rising action, crisis, climax, resolution. Link structural moments to dramatic devices and their effect on the audience." },
    { question: "Evaluate how technical theatre elements (lighting, sound, set and costume) work together to create a unified production concept in a play you have studied. (10 marks)", answer: "A unified production concept means all design elements share a coherent visual and thematic language. Example: a production of Macbeth might use: Lighting — high contrast chiaroscuro, dark shadows, blood-red specials for supernatural scenes, white cold wash for the natural world; Sound — dissonant underscoring, whispered voices for the witches, silence for moments of moral decision; Set — minimal, skeletal black steel structure suggesting a corrupted world stripped bare; Costume — Macbeth in military grey that darkens to black as he descends. The concept unifies because every element communicates the theme of corruption and moral darkness. Analysis should evaluate how well the design choices serve the thematic purpose — are there moments where design and performance work against each other? Are there moments of particular brilliance where all elements converge?", marks: 10, hint: "Identify an overarching concept, then show how each design area (lighting, sound, set, costume) serves it. Evaluate coherence and effectiveness." },
    { question: "How does the choice of practitioner's approach (Stanislavski, Brecht, Artaud, or physical theatre) shape the theatrical experience for an audience? Analyse with reference to a specific production or performance style you have studied. (12 marks)", answer: "Framing: the practitioner's approach determines the relationship between performer and audience, what the audience is asked to do (feel, think, experience), and what the theatre itself claims to be. Stanislavski creates an illusory world the audience believes in — the theatrical experience is one of empathy, emotional identification and catharsis. The audience leaves having felt something deeply personal. Brecht creates a critical forum — the theatrical experience is one of intellectual engagement, questioning social structures, and potentially political awakening. The audience leaves with ideas, not just feelings. Artaud creates a sensory assault — the theatrical experience is visceral, disorienting, and potentially traumatic. The audience's rational defences are broken down; they experience something like a collective ritual. Physical theatre (Frantic Assembly, DV8) creates a primarily kinetic experience — the body communicates what words cannot. The audience responds somatically, feeling movement in their own bodies. Evaluation should address: which practitioner's approach is most appropriate for which type of story? How does knowing the approach shape audience expectation and interpretation? Is there value in combining approaches?", marks: 12, hint: "Analyse how each practitioner's approach creates a different audience experience — emotional, intellectual, visceral, or kinetic. Reference specific productions or works." },
    { question: "Analyse how a non-naturalistic production you have studied uses theatrical conventions to challenge or engage its audience. Evaluate how effectively the production achieved its theatrical aims. (10 marks)", answer: "Non-naturalistic theatre deliberately breaks theatrical conventions to create a different kind of engagement. Conventions to discuss: breaking the fourth wall (direct address forces the audience to acknowledge they are watching); multi-role (reminds the audience that acting is a craft, not an illusion); placards and narration (Brechtian — remind the audience of the constructed nature of the narrative); physical theatre (the body as text — storytelling through movement rather than words); non-realistic set and costume (symbolic rather than literal — demanding the audience interpret rather than simply observe). Each convention should be linked to a theatrical effect: alienation, immersion, comedy, unease, political awakening, physical empathy. Evaluation: were these conventions consistently applied? Did the non-naturalistic approach serve the story? Were there moments of particular theatrical power? Did the approach create genuine audience engagement or confusion? A strong answer evaluates both success and limitations.", marks: 10, hint: "Identify at least three non-naturalistic conventions, explain what each achieves, and evaluate overall effectiveness. Be specific about theatrical moments." },
  ],
  flashcard: [
    { term: "Stanislavski's System", definition: "Method acting approach: emotional memory, given circumstances, 'magic if', units and objectives, super-objective, method of physical actions. Aims for psychological truth and naturalistic performance.", example: "An actor recalling a real emotional memory to make grief on stage authentic" },
    { term: "Brecht and Epic Theatre", definition: "Epic Theatre prevents emotional immersion using Verfremdungseffekt (alienation effect): direct address, placards, narration, multi-role, gestus. Audience must think critically, not just feel.", example: "Mother Courage: actors remind audience they are watching a play throughout" },
    { term: "Physical Theatre", definition: "Performance style where the body is the primary storytelling tool — movement, gesture and physicality over words. Practitioners include DV8, Frantic Assembly, Complicité.", example: "Frantic Assembly's 'Hymn Hands' exercise builds scenes from physical contact and movement" },
    { term: "Verfremdungseffekt", definition: "Brecht's 'alienation effect' — making the familiar seem strange to prevent emotional absorption and encourage critical thinking about social issues presented on stage.", example: "An actor suddenly stepping out of character to narrate events from outside" },
    { term: "Semiotics in Theatre", definition: "The study of signs and symbols in performance. Everything on stage — costume, lighting, set, gesture — is a sign communicating meaning. Directors make intentional semiotic choices.", example: "Red lighting = danger/passion; a broken chair = poverty/dysfunction" },
    { term: "Proxemics", definition: "The use of physical space and distance between performers to communicate relationship, power and emotion. Close proximity suggests intimacy or confrontation; distance suggests formality or isolation.", example: "Two characters stand very close — the audience reads this as either intimacy or threat" },
    { term: "Gestus", definition: "Brechtian term for a gesture, posture or attitude that reveals a character's social position and attitude. Represents class and power rather than individual psychology.", example: "A factory owner who constantly looks at their watch — gestus of power and ownership of time" },
    { term: "Theatre of Cruelty", definition: "Antonin Artaud's approach: assault the senses with light, sound and spectacle to create a visceral, ritualistic experience that breaks down rational defences. 'Cruelty' means rigour and intensity, not violence.", example: "Audience surrounded by performers, sound coming from all directions, no traditional staging" },
    { term: "Proscenium Arch", definition: "Traditional staging where audience sits on one side and the stage is framed like a picture. Creates formality and distance. Good for spectacle and large-scale productions.", example: "West End theatres, traditional opera houses" },
    { term: "In-the-Round", definition: "Staging configuration where the audience surrounds the stage on all sides. Creates maximum intimacy and vulnerability — actors cannot hide. Audience see each other across the stage.", example: "The Globe Theatre (original configuration), Chichester Festival Theatre" },
    { term: "Emotional Memory", definition: "Stanislavski technique where an actor recalls a real personal emotional experience to generate authentic feeling on stage. Controversial but central to Method acting.", example: "An actor recalling the death of a pet to produce genuine grief in a mourning scene" },
    { term: "Devising", definition: "Creating original theatre from scratch, without a pre-existing script. May begin from a stimulus (image, object, theme, text). Involves collaboration, improvisation, research and structured rehearsal.", example: "Frantic Assembly devising 'Stockholm' from movement exercises and personal stories" },
    { term: "Fourth Wall", definition: "The imaginary wall between performers and audience in naturalistic theatre. Performers pretend the audience does not exist. Breaking the fourth wall (direct address) is a non-naturalistic technique.", example: "Brecht's theatre deliberately breaks the fourth wall to prevent emotional immersion" },
    { term: "Super-Objective", definition: "Stanislavski's term for the overarching want or goal that drives a character throughout the entire play. All smaller scene objectives serve the super-objective.", example: "Macbeth's super-objective: to secure and maintain power. Every scene objective serves this." },
    { term: "Catharsis", definition: "Aristotle's concept that tragedy produces emotional release (purging of pity and fear) in the audience. Naturalistic theatre often aims for catharsis; Brecht deliberately avoided it.", example: "Watching Oedipus discover the truth — audience experiences fear and pity, then emotional release" },
    { term: "Thrust Stage", definition: "A stage that extends into the audience area, with audience on three sides. Creates greater intimacy than proscenium but allows larger scenes than in-the-round. Shakespeare's Globe used a thrust stage.", example: "Shakespeare's Globe, Cottesloe Theatre, many studio theatres" },
    { term: "Dramatic Irony", definition: "When the audience knows something that one or more characters on stage do not. Creates tension, suspense, or dark comedy as the audience watches characters act without crucial knowledge.", example: "In Macbeth, the audience knows Duncan is about to be murdered — Duncan does not" },
    { term: "Subtext", definition: "The underlying meaning beneath what is actually said. What a character truly thinks or feels beneath their words. Naturalistic actors must find and play the subtext of every scene.", example: "'I'm fine' — the words suggest calm but the subtext (and body language) reveals distress" },
    { term: "Chiaroscuro (Lighting)", definition: "Dramatic contrast between lit and unlit areas on stage. Creates mystery, tension and atmosphere. Draws the eye to specific areas while leaving others in darkness. Borrowed from painting (Caravaggio).", example: "A single shaft of light on a character's face while the rest of the stage is in darkness" },
    { term: "Verbatim Theatre", definition: "Documentary theatre using real people's exact words taken from interviews, court documents or recordings as the script. Creates a direct link between theatrical performance and real events.", example: "The Lehman Trilogy and London Road both use verbatim or near-verbatim testimony" },
    { term: "Traverse Staging", definition: "Stage placed between two banks of audience seating, creating a corridor of action. Audience on two sides. Good for processional narratives and journeys. Creates a long, narrow performance space.", example: "Many studio theatre productions use traverse to create a sense of journey or confrontation" },
    { term: "Blocking", definition: "The pre-planned movement of actors on stage — where they stand, when and where they move, and why. Planned by the director to create visual composition, ensure sightlines, and communicate meaning.", example: "A director blocks a character downstage centre for power — and another upstage and isolated for vulnerability" },
    { term: "Given Circumstances", definition: "Stanislavski's term for the facts of a character's situation established by the playwright: who they are, where they are, when, what has happened before, and what they want. Actors must believe these fully.", example: "Hamlet's given circumstances: Prince of Denmark, father murdered by uncle, mother remarried — every scene is shaped by this" },
    { term: "Diegetic vs Non-Diegetic Sound", definition: "Diegetic: sound that exists within the world of the play — characters can hear it. Non-diegetic: sound added for the audience's effect only — characters cannot hear it (e.g. underscoring, atmospheric sound design).", example: "A character plays a radio on stage (diegetic); ominous underscoring heard only by the audience (non-diegetic)" },
    { term: "Absurdist Theatre", definition: "Theatre presenting a world without inherent meaning, logic or purpose. Characters are often trapped in meaningless repetition or impossible situations. Associated with Samuel Beckett and Harold Pinter (Theatre of the Absurd, 1950s).", example: "Waiting for Godot: two characters wait indefinitely for Godot, who never arrives — futility and repetition" },
  ],
};
